import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */

import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { edit_and_get_delete_resource } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import OverlayComp from "@/components/OverlayComp.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  props: {
    rowData: Object
  },
  components: {
    OverlayComp,
    SnackBar
  },
  mixins: [get_all_org_users],
  data() {
    return {
      resourceName: "",
      resourceDescription: "",
      fromMenu: false,
      formTime: "",
      toTimeMenu: false,
      toTime: "",
      slotsitems: [],
      slots: "",
      priorBooking: null,
      hourlyBasics: "",
      globalItems: [],
      dayBasics: "",
      paymentCost: "",
      slotPayed: false,
      userArray: [],
      cordinatoarMembers: "",
      loading: false,
      currency: "",
      overlay: false,
      SnackBarComponent: {},
      valueChange: false,
      globalresponse: {}
    };
  },
  async mounted() {
    this.overlay = true;
    this.generate_interval_options();
    this.$store.commit("Setnamesearch", "");
    await this.get_all_org_users();
    this.fetch_details();
    await this.get_resource_details();
  },
  methods: {
    onlyNumbers(event) {
      if (!/[0-9]/.test(event.key)) {
        event.preventDefault();
      }
    },
    back_call() {
      this.$emit("backAction", 0);
    },
    async get_resource_details() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_and_get_delete_resource, {
          input: {
            action_type: "GET",
            organization_id: data.organization.organization_id,
            resource_id: this.rowData.resource_id
          }
        }));
        var response = JSON.parse(result.data.edit_and_get_delete_resource);
        this.overlay = false;
        // console.log(response);
        if (response.Status == "SUCCESS") {
          this.globalresponse = response;
          this.resourceName = response.data.resource_name;
          this.resourceDescription = response.data.resource_description;
          this.formTime = response.data.resource_slot_availabity.start_time;
          this.toTime = response.data.resource_slot_availabity.end_time;
          this.slots = response.data.resource_slot_duration;
          this.priorBooking = this.fetch_prioir_data(response.data.resource_booking_time_ahead);
          this.slotPayed = response.data.is_resource_slot_paid;
          this.paymentCost = response.data.is_resource_slot_paid == true ? response.data.resource_slot_price : "";
          this.currency = response.data.is_resource_slot_paid == true ? response.data.resource_amount_type : "";
          this.cordinatoarMembers = response.data.resource_slot_cordinators.length != 0 ? response.data.resource_slot_cordinators[0].full_user_name : "";

          //   this.tableData = response.data;
        } else {}
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    fetch_prioir_data(value) {
      var data = "";
      if (value == "IMMEDIATE") {
        data = "immediate";
      } else if (value.endsWith("hours") == true) {
        data = "hours";
        this.get_hourly(24);
        this.hourlyBasics = value;
        // this.hourlyBasics = value.replace("_hours", " ");
      } else if (value.endsWith("days") == true) {
        data = "days";
        this.get_hourly(5);
        // this.dayBasics = value.replace("_days", " ");
        this.dayBasics = value;
      }
      return data;
    },
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id,
            user_email_id: element.user_email_id
          });
        }
      });
    },
    generate_interval_options() {
      this.slotsitems = [];
      const durations = [15, 30, 60, 120, 180, 240, 300, 360, 420, 480, 540, 600, 660, 720, 780, 840, 900, 960, 1020, 1080, 1140, 1200, 1260, 1320, 1380, 1440];
      for (const duration of durations) {
        let value;
        if (duration < 60) {
          value = `${duration}_Minutes`;
        } else {
          value = `${Math.floor(duration / 60)}_Hour`;
        }
        const label = value.replace("_", " ");
        this.slotsitems.push({
          title: label,
          value
        });
      }
    },
    get_hourly(val) {
      this.globalItems = [];
      for (var i = 1; i <= val; i++) {
        this.globalItems.push({
          title: i,
          value: val == 24 ? i + "_hours" : i + "_days"
        });
      }
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        // console.log( this.dayBasics);
        // this.fetch_cordinators();
        this.update_respource_type();
      }
    },
    async update_respource_type() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_and_get_delete_resource, {
          input: {
            organization_id: data.organization.organization_id,
            resource_name: this.resourceName,
            action_type: "UPDATE",
            resource_id: this.rowData.resource_id,
            resource_slot_availabity: this.fetch_slot2_avliablity(),
            resource_images: JSON.stringify(this.rowData.resource_images),
            resource_booking_time_ahead: this.fetch_prior_booking(),
            resource_slot_duration: this.slots,
            is_resource_slot_paid: this.slotPayed,
            resource_slot_cordinators: this.fetch_cordinators(),
            resource_slot_price: this.slotPayed == true ? this.paymentCost : undefined,
            resource_description: this.resourceDescription,
            resource_amount_type: this.slotPayed == true ? this.currency : undefined
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_and_get_delete_resource);
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    fetch_cordinators() {
      var data = [];
      if (this.valueChange == true) {
        data.push(this.cordinatoarMembers);
      } else {
        data = this.globalresponse.data.resource_slot_cordinators;
      }
      return JSON.stringify(data);
    },
    get_selected_data() {
      this.valueChange = true;
    },
    fetch_slot2_avliablity() {
      var data = {
        start_time: this.formTime,
        end_time: this.toTime
      };
      return JSON.stringify(data);
    },
    fetch_prior_booking() {
      var data = "";
      if (this.priorBooking == "immediate") {
        data = "IMMEDIATE";
      } else if (this.priorBooking == "hours") {
        // data = this.hourlyBasics + "_" + "hours";
        data = this.hourlyBasics;
      } else if (this.priorBooking == "days") {
        // data = this.dayBasics + "_" + "days";
        data = this.dayBasics;
      }
      return data;
    }
  }
};
